 */
const mergeUnique = mixer({
  deep: true,
  noOverwrite: true
});

/**
 * Merge objects including prototype chain properties.
 */
const mergeChainNonFunctions = mixer({
  filter: isNotFunction,
  deep: true,
  chain: true
});

export default mixer;
export {
