  // When fed repetitive line-break sequences, these patterns trigger catastrophic backtracking.

  // Crafted payload: Each "\r\n" pair can be ambiguously parsed by the RE2/V8 engine
  // as multiple valid \s matches before failing. This forces exponential path exploration.
  const maliciousInput = '\r\n'.repeat(50000);

