+ * @param {import("regexpp/ast").Node} node
+ * @returns {boolean}
+ */
+function underAStar(node) {
+  if (node.type === "Quantifier" && node.max > 10) {
+    return true;
+  } else if (node.parent) {
+    return underAStar(node.parent);
+  } else {
+    return false;
+  }
