    var expression = sibling.get('expression');

    if (!expression.isAssignmentExpression()) {
      return false;
    }

    var left = expression.get('left');

    if (!left.isMemberExpression()) {
      return false;
    }

    var leftObject = left.get('object');

    if (!leftObject.isMemberExpression()) {
      return false;
