  console.log(`[PoC] Input length: ${maliciousInput.length}`);
  console.log(`[PoC] Estimated backtracks: ~${n * n} (exceeds 30,000 limit)`);

  const start = Date.now();

  // Invoking parseInline forces the lexer to evaluate all inline rules.
  // The autolink rule's match function calls .exec() on this input.
  // This will trigger the catastrophic backtracking and throw an exception 
  // when the backtrack count exceeds 30,000.
